<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class Booking extends Model{protected $fillable=['reference','tour_id','tour_departure_id','pickup_point_id','type','status','first_name','last_name','phone','email','whatsapp','date_of_birth','age','address','participant_count','comments','special_requests','mobility_information','food_allergies','meal_selection','promo_code','source','emergency_contact_name','emergency_contact_phone','roommate_request','currency','total_amount','deposit_amount','amount_paid','payment_status','payment_proof','policies_accepted_at','terms_accepted_at','privacy_accepted_at','marketing_consent','waiver_accepted_at','waiver_text','internal_notes','submission_token','confirmation_sent_at','seat_notice_sent_at','updated_by'];public const STATUSES=['new'=>'New','payment_pending'=>'Payment pending','confirmed'=>'Confirmed','cancelled'=>'Cancelled','completed'=>'Completed','contacted'=>'Contacted'];public const PAYMENT_STATUSES=['unpaid'=>'Unpaid','proof_submitted'=>'Proof submitted','deposit_paid'=>'Deposit paid','paid'=>'Fully paid','refunded'=>'Refunded'];protected $casts=['date_of_birth'=>'date','age'=>'integer','total_amount'=>'decimal:2','deposit_amount'=>'decimal:2','amount_paid'=>'decimal:2','policies_accepted_at'=>'datetime','terms_accepted_at'=>'datetime','privacy_accepted_at'=>'datetime','waiver_accepted_at'=>'datetime','marketing_consent'=>'boolean','confirmation_sent_at'=>'datetime','seat_notice_sent_at'=>'datetime'];protected static function booted():void{static::creating(fn($m)=>$m->reference??='DT-'.strtoupper(Str::random(8)));
  // Any change to who is travelling on which date re-counts that date's seats (and the old date's, if moved).
  static::saved(function(Booking $b){if($b->wasChanged(['status','participant_count','tour_departure_id'])||$b->wasRecentlyCreated){TourDeparture::find($b->tour_departure_id)?->recountSeats();if($b->wasChanged('tour_departure_id'))TourDeparture::find($b->getOriginal('tour_departure_id'))?->recountSeats();}});
  static::deleted(fn(Booking $b)=>TourDeparture::find($b->tour_departure_id)?->recountSeats());}
 public function updatedBy(){return $this->belongsTo(User::class,'updated_by');}public function tour(){return $this->belongsTo(Tour::class);}public function departure(){return $this->belongsTo(TourDeparture::class,'tour_departure_id');}public function pickupPoint(){return $this->belongsTo(PickupPoint::class);}public function passengers(){return $this->hasMany(BookingPassenger::class)->orderBy('room_number')->orderBy('id');} /** True when the passengers on this booking board at different pickup points. */ public function hasMixedPickups(): bool{return $this->passengers->pluck('pickup_point_id')->filter()->unique()->count()>1;} public function getBalanceDueAttribute(): float{return max(0,(float)$this->total_amount-(float)$this->amount_paid);}}
